content:
[
  {
    "tag": "开场钩子",
    "prompt": "你是抖音爆款脚本师，请为主题{{主题}}写5个3秒开场钩子，每条不超过20字，必须包含悬念或冲突，并标注钩子类型。",
    "usage": "短视频开头留人时快速生成多个开场方案。",
    "example": "1.【悬念】为什么90%的人第一步就做错了？"
  },
  {
    "tag": "反差钩子",
    "prompt": "围绕{{产品卖点}}创作3条反差型钩子，前一句制造常识认知，后一句用反转打破它，每条限25字内，附一句引导停留的话术。",
    "usage": "带货视频需要制造认知冲突吸引停留时使用。",
    "example": "越贵的越省钱？这条视频告诉你真相，先别划走。"
  },
  {
    "tag": "痛点钩子",
    "prompt": "针对{{目标人群}}在{{场景}}中的痛点，写4条共情式钩子，每条用第二人称直击痛点，15到25字，并给出情绪词标注。",
    "usage": "面向特定人群做情感共鸣类视频开头。",
    "example": "每天加班到深夜，工资却不见涨？【焦虑】"
  },
  {
    "tag": "好奇钩子",
    "prompt": "以{{话题}}为核心，写5条激发好奇心的钩子，必须包含具体数字或结果承诺，控制在30字内，并说明每条钩子利用了哪种好奇机制。",
    "usage": "知识科普或经验分享类视频提升完播率。",
    "example": "只改了1个习惯，我3个月涨粉10万，方法很简单。"
  },
  {
    "tag": "悬念钩子",
    "prompt": "为{{故事或事件}}设计3条层层递进的悬念钩子，第一条抛出疑问，第二条暗示结果，第三条预告反转，每条20字内。",
    "usage": "剧情类或案例复盘类短视频开头编排。",
    "example": "他辞职那天，老板笑了；三个月后，老板却……"
  },
  {
    "tag": "数字钩子",
    "prompt": "用数字结构为主题{{主题}}写4条钩子，格式含具体数量和收益承诺，如{{数量}}个方法或步骤，每条不超过25字并标注数字亮点。",
    "usage": "干货清单类视频开头突出信息密度。",
    "example": "3个动作，7天改善圆肩驼背，亲测有效。"
  },
  {
    "tag": "提问钩子",
    "prompt": "围绕{{用户关心的问题}}生成5条提问式钩子，问题要具体可回答且带争议性，每条15字内，并给出评论区引导语。",
    "usage": "提升互动率和评论量的视频开头。",
    "example": "月薪5000该不该买奢侈品？评论区吵翻了。"
  },
  {
    "tag": "场景钩子",
    "prompt": "为{{产品或服务}}写3条场景化钩子，先描述用户熟悉的{{具体场景}}，再引出解决方案，每条30字内，要求画面感强。",
    "usage": "生活类或产品种草视频开头代入场景。",
    "example": "早上赶地铁没时间吃早餐？这个30秒搞定。"
  },
  {
    "tag": "权威钩子",
    "prompt": "以{{专业身份或数据来源}}为背书，为{{主题}}写3条权威型钩子，需包含可信来源或身份标识，每条25字内并标注可信点。",
    "usage": "专业领域视频快速建立信任感。",
    "example": "从业10年的皮肤科医生：这3个护肤误区别再犯。"
  },
  {
    "tag": "情绪钩子",
    "prompt": "针对{{情绪触发点}}写4条强情绪钩子，分别覆盖愤怒、感动、惊喜、焦虑四种情绪，每条20字内，并标注对应情绪及适用人群。",
    "usage": "需要情绪驱动转发和点赞的视频开头。",
    "example": "看到最后我哭了，这个父亲的做法太戳心。【感动】"
  }
]
